import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"For Agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md","lastUpdated":1792596230000}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="for-agents" tabindex="-1">For Agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to “For Agents”">​</a></h1><p>在项目里接入曦寒流程设计器时，怎样让 Claude Code、Cursor、Codex、GitHub Copilot 这类 AI 编程工具写出符合约定的代码。</p><p>流程设计器没有单独的命令行或 MCP 服务端。AI 工具需要的资料分三处：本站的<a href="./llms">机读文档</a>、流程用到的 <a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI</a> 的 MCP 服务端，以及改流程仓库本身时读的仓库根 <code>AGENTS.md</code>。</p><h2 id="复制这段提示词" tabindex="-1">复制这段提示词 <a class="header-anchor" href="#复制这段提示词" aria-label="Permalink to “复制这段提示词”">​</a></h2><p>把下面这段放进对话，或补进你项目的 <code>AGENTS.md</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个项目用曦寒流程设计器（@xihan-flow/core、@xihan-flow/runtime、@xihan-flow/designer），以原生 Web Components 交付。</span></span>
<span class="line"><span>API 以项目里装的版本为准，不要凭记忆写：先读 https://flow.docs.xihanfun.com/llms.txt，按需读其中列出的页面（站点地址后加 .md 取 Markdown）。</span></span>
<span class="line"><span>- 流程定义是纯 JSON，属性叫 schema，变化事件叫 schema-change；节点类型、属性、规则、命令、面板都经 extensions 登记，不改设计器源码。</span></span>
<span class="line"><span>- 查看器用 defineFlowViewer() 注册，设计器用 defineFlowDesigner() 注册；样式引 @xihan-ui/styles，设计器另引 @xihan-ui/designer-shell/style.css 与 @xihan-flow/designer/style.css。</span></span>
<span class="line"><span>- 对接 XiHan.Framework 工作流引擎时装 @xihan-flow/core/presets/xihan-workflow 预设，用 toWorkflowDefinition / fromWorkflowDefinition 与引擎定义互转。</span></span>
<span class="line"><span>- 保存、权限与取数归宿主：设计器不发网络请求；保存前看 validate()，服务端用 validateDocument 复核。</span></span>
<span class="line"><span>用到 XiHan.UI 的组件、令牌与语言包时，读 https://ui.docs.xihanfun.com/llms.txt，或接入 XiHan.UI 的 MCP 服务端。</span></span></code></pre></div><h2 id="要装的包" tabindex="-1">要装的包 <a class="header-anchor" href="#要装的包" aria-label="Permalink to “要装的包”">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>什么时候装</th></tr></thead><tbody><tr><td><code>@xihan-flow/core</code></td><td>都要：流程定义的类型、读入、校验与编辑操作，以及 XiHan 工作流引擎预设</td></tr><tr><td><code>@xihan-flow/runtime</code></td><td>显示流程、标出运行状态：<code>&lt;xh-flow-viewer&gt;</code></td></tr><tr><td><code>@xihan-flow/designer</code></td><td>编辑流程：<code>&lt;xh-flow-designer&gt;</code></td></tr><tr><td><code>@xihan-ui/styles</code></td><td>设计令牌与组件皮肤，查看器与设计器的样式都取自它</td></tr><tr><td><code>@xihan-ui/designer-shell</code></td><td>用设计器时引它的样式表</td></tr></tbody></table><p>流程各包用到的 <code>@xihan-ui/*</code> 写在 peerDependencies 里，pnpm 与 npm 7 起会自动装上；项目里自己也用 XiHan.UI 时，流程与项目共用同一份。安装命令与第一个示例见<a href="./../quickstart">快速开始</a>。</p><h2 id="关键约定" tabindex="-1">关键约定 <a class="header-anchor" href="#关键约定" aria-label="Permalink to “关键约定”">​</a></h2><ul><li><strong>模板即数据</strong>：流程定义是纯 JSON，不含也不执行代码；导入别人给的定义不会注入脚本。从存储或接口取回的定义先交给 <code>readDocument</code> 检查字段，见<a href="./../guide/schema">流程定义结构</a>。</li><li><strong>经扩展登记，不改源码</strong>：节点类型、属性与编辑方式、校验规则、节点渲染、命令、面板、物料来源、设置分区、引导步骤与导入导出，都写进 <code>extensions</code>，见<a href="./../guide/extensions">扩展</a>。</li><li><strong>数据由宿主提供</strong>：查看器与设计器不发网络请求；模板的保存、权限、受理人这类业务数据与服务端复核都归宿主，见<a href="./../guide/host">与宿主集成</a>。</li><li><strong>样式只取令牌</strong>：元素用 Light DOM，颜色、间距、圆角都取 XiHan.UI 的设计令牌，宿主换主题或主题色，流程跟着变。</li><li><strong>文案按语言包合并</strong>：流程的语言包（如 <code>flowZhCN</code>）与 XiHan.UI 同一语言的语言包合并后全局设置，见<a href="./../quickstart">快速开始</a>。</li><li><strong>工作流引擎预设</strong>：<code>@xihan-flow/core/presets/xihan-workflow</code> 把 XiHan.Framework 工作流引擎的每种活动做成一个节点类型，属性键与引擎读的一致，规则与引擎发布时的检查对齐，见 <a href="./../guide/xihan-workflow">XiHan 工作流引擎预设</a>。</li></ul><h2 id="改流程仓库本身" tabindex="-1">改流程仓库本身 <a class="header-anchor" href="#改流程仓库本身" aria-label="Permalink to “改流程仓库本身”">​</a></h2><p>给 XiHan.FlowDesigner 提交代码时，仓库根的 <code>AGENTS.md</code> 写明了目录结构、常用命令、分层与依赖、硬性约定、发版与提交规范；<code>CLAUDE.md</code> 链接到它，Claude Code 与 Codex 打开仓库即可读到。Cursor、GitHub Copilot 等工具可以在各自的规则文件里写一句「先读仓库根的 AGENTS.md」。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./llms">LLMs.txt</a> · <a href="./../quickstart">快速开始</a> · <a href="./../guide/extensions">扩展</a> · <a href="./../guide/host">与宿主集成</a></li><li><a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI 的 AI 辅助开发</a> · <a href="https://framework.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.Framework 的 AI 辅助开发</a></li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};